<script setup lang="ts">
import { computed, onMounted, reactive, ref } from 'vue'; import { ArrowLeft, RefreshCw, ShieldCheck, Ticket } from 'lucide-vue-next'; import { useRoute, useRouter } from 'vue-router'; import AppLogo from '@/components/AppLogo.vue'; import { api } from '@/services/api'; import { errorMessage } from '@/services/http'; import { useAuthStore } from '@/stores/auth'; import type { Role } from '@/types'
const route=useRoute(); const router=useRouter(); const auth=useAuthStore(); const role=computed<Role>(()=>route.query.role==='ADMIN'?'ADMIN':'USER'); const form=reactive({username:'',password:'',captchaCode:''}); const captcha=ref({id:'',image:''}); const loading=ref(false); const error=ref('')
async function refresh(){const value=await api.captcha('LOGIN'); captcha.value={id:value.captchaId,image:value.imageBase64}}
async function submit(){error.value=''; loading.value=true; try{await auth.login({...form,captchaId:captcha.value.id},role.value); router.push(String(route.query.redirect|| (role.value==='ADMIN'?'/admin':'/user')))}catch(e){error.value=errorMessage(e); await refresh()}finally{loading.value=false}}
onMounted(refresh)
</script>
<template><main class="auth-page"><section class="auth-aside"><AppLogo/><div><span class="auth-symbol"><component :is="role==='ADMIN'?ShieldCheck:Ticket"/></span><p class="eyebrow">{{role==='ADMIN'?'OPERATIONS':'PASSENGER'}}</p><h1>{{role==='ADMIN'?'高效管理每一段旅程':'欢迎回来，继续你的旅程'}}</h1><p>{{role==='ADMIN'?'集中维护铁路基础数据与票务资源。':'登录后即可查询余票、管理订单和查看乘车通知。'}}</p></div></section><section class="auth-panel"><div class="auth-form"><RouterLink to="/" class="back"><ArrowLeft/>重新选择身份</RouterLink><h2>{{role==='ADMIN'?'管理员登录':'用户登录'}}</h2><p class="muted">请输入账号信息完成身份验证</p><p v-if="route.query.registered==='1'" class="notice">注册成功，请使用新账号登录</p><form @submit.prevent="submit"><label>用户名<input v-model.trim="form.username" required maxlength="64" placeholder="请输入用户名"></label><label>密码<input v-model="form.password" required type="password" minlength="8" placeholder="请输入密码"></label><label>验证码<div class="captcha-row"><input v-model.trim="form.captchaCode" required maxlength="4" placeholder="输入验证码"><button type="button" class="captcha-image" @click="refresh"><img v-if="captcha.image" :src="captcha.image" alt="验证码"><RefreshCw/></button></div></label><p v-if="error" class="form-error">{{error}}</p><button class="btn primary wide" :disabled="loading">{{loading?'正在登录…':'登录'}}</button></form><p v-if="role==='USER'" class="auth-switch">还没有账号？<RouterLink to="/register">立即注册</RouterLink></p><p v-else class="admin-hint">管理员账号由系统初始化，不支持在线注册</p></div></section></main></template>
